datasets <- list(
  data1 = c(1, 2, 3)
)
transform <- list(
  log = function(x) { Sys.sleep(0.1); log(x) },
  sqrt = function(x) { Sys.sleep(0.1); sqrt(x) }
)
transform2 <- list(
  plus = function(x) { Sys.sleep(0.1); x + 1 },
  minus = function(x) { Sys.sleep(0.1); x - 1 }
)
res2 <- datasets %>% time_methods(transform) %>% time_methods(transform2)
res2 %>% unpack_timing()
res2 %>% strip_timing()
